    status, x, y, q = solve_primal(model)
    if status == 0 and x is not None:
        return optimal_with_certificate(model, x, y, q)
    # the canonical LP is infeasible (or the solver failed): a Farkas witness
    # proves infeasibility on its own
    cert = farkas_certificate(model)
    if cert is not None:
