        if y2 is not None:
            return optimal_with_certificate(model, x2, y2, q2)
        return optimal_response(model, x2, np.zeros(model.R),
                                np.zeros(model.K))[0]
    return {"epoch": model.epoch, "status": "infeasible",
            "certificate": {"inequality": [0.0] * model.R,
